-- PostgreSQL schema created automatically when the Vasooli API starts.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS msmes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, udyam TEXT UNIQUE NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS buyers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, phone TEXT NOT NULL, email TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS invoices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), msme_id UUID NOT NULL REFERENCES msmes(id), buyer_id UUID NOT NULL REFERENCES buyers(id), invoice_number TEXT NOT NULL, amount NUMERIC(14,2) NOT NULL, invoice_date DATE NOT NULL, due_date DATE NOT NULL, language TEXT NOT NULL CHECK (language IN ('hi','ta','en')), status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','nudged','noticed','called','overdue','filed','paid')), days_elapsed INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(msme_id, invoice_number));
CREATE TABLE IF NOT EXISTS calls (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id UUID NOT NULL REFERENCES invoices(id), direction TEXT NOT NULL CHECK (direction IN ('inbound','outbound')), transcript TEXT NOT NULL, outcome TEXT NOT NULL CHECK (outcome IN ('promise_to_pay','dispute','voicemail','no_answer')), promise_date DATE, duration_seconds INTEGER NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS complaints (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id UUID UNIQUE NOT NULL REFERENCES invoices(id), principal NUMERIC(14,2) NOT NULL, interest NUMERIC(14,2) NOT NULL, total NUMERIC(14,2) NOT NULL, rbi_rate NUMERIC(6,2) NOT NULL, days_overdue INTEGER NOT NULL, pdf_url TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','filed')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
